/* QTL browsing inside the research-route page. Catalogue references do not mutate a plan. */
'use strict';
(()=>{
  const LANGS=['zh','en','fr','es','eu'],FAMILIES=['rna_core','context','variance','additional_omics'];
  const COPY={
    evolution:['贝叶斯与进化','Bayesian & evolution','Bayésien et évolution','Bayes y evolución','Bayes eta eboluzioa'],
    coverage:['研究覆盖图','Research coverage','Couverture scientifique','Cobertura científica','Ikerketa-estaldura'],
    navigation:['研究路线视图','Research route views','Vues des axes de recherche','Vistas de investigación','Ikerketa-ildoen ikuspegiak'],allRoutes:['全部研究路线','All research routes','Tous les axes de recherche','Todas las líneas de investigación','Ikerketa-ildo guztiak'],qtlTraits:['QTL 性状','QTL traits','Caractères QTL','Rasgos QTL','QTL ezaugarriak'],title:['QTL 研究路线','QTL research routes','Axes de recherche QTL','Líneas de investigación QTL','QTL ikerketa-ildoak'],
    intro:['按目标性状与数据类型比较 QTL，查看对应的研究路线与来源。','Compare QTLs by trait and data type, then inspect the linked research routes and sources.','Comparez les QTL par caractère et type de données, puis consultez les axes et les sources associés.','Compare QTL por rasgo y tipo de datos y consulte las líneas de investigación y sus fuentes.','Alderatu QTLak ezaugarriaren eta datu motaren arabera, eta ikusi lotutako ikerketa-ildoak eta iturriak.'],
    search:['搜索缩写、全名或性状','Search abbreviation, full name or trait','Rechercher un sigle, un nom ou un caractère','Buscar sigla, nombre completo o rasgo','Bilatu laburdura, izen osoa edo ezaugarria'],
    searchHint:['例如 eQTL、表达方差、剪接','For example: eQTL, expression variance, splicing','Par exemple : eQTL, variance d’expression, épissage','Por ejemplo: eQTL, varianza de expresión, empalme','Adibidez: eQTL, adierazpen-bariantza, splicing'],
    filters:['按研究内容筛选','Filter by research focus','Filtrer par sujet','Filtrar por enfoque','Iragazi ikerketa-gaiaren arabera'],
    all:['全部','All','Tous','Todos','Guztiak'],rna_core:['RNA 性状','RNA traits','Caractères ARN','Rasgos de ARN','RNA ezaugarriak'],context:['状态与情境','State and context','État et contexte','Estado y contexto','Egoera eta testuingurua'],variance:['方差与比较','Variance and comparison','Variance et comparaison','Varianza y comparación','Bariantza eta konparazioa'],additional_omics:['额外组学','Additional omics','Autres omiques','Ómicas adicionales','Omika osagarriak'],
    reset:['清除筛选','Clear filters','Effacer les filtres','Borrar filtros','Garbitu iragazkiak'],matches:['项匹配','matches','résultats','resultados','emaitza'],of:['共','of','sur','de','guztira'],
    details:['研究设计与数据要求','Design and data requirements','Plan d’étude et données nécessaires','Diseño y datos necesarios','Diseinua eta beharrezko datuak'],
    metrics:['参考指标','Reference measures','Indicateurs de référence','Medidas de referencia','Erreferentziako neurriak'],unit:['统计单位','Statistical unit','Unité statistique','Unidad estadística','Unitate estatistikoa'],inputs:['关联输入资料','Relevant input material','Données pertinentes','Datos de entrada pertinentes','Sarrerako material garrantzitsua'],additionalInputs:['额外数据或记录','Additional data or records','Données ou documents supplémentaires','Datos o registros adicionales','Datu edo erregistro osagarriak'],inputModes:['不同分析路径的输入','Inputs by analysis route','Entrées selon la démarche','Entradas según la vía de análisis','Analisi-bidearen araberako sarrerak'],scope:['酵母短读单细胞适用性','Applicability to yeast short-read single-cell data','Application aux données unicellulaires de levure à lectures courtes','Aplicación a datos unicelulares de levadura de lecturas cortas','Aplikagarritasuna legamiaren irakurketa laburreko zelula bakarreko datuetarako'],biologyCaveat:['解释要点','Interpretation','Interprétation','Interpretación','Interpretazioa'],tools:['相关方法','Related methods','Méthodes associées','Métodos relacionados','Lotutako metodoak'],sources:['文献与方法来源','Literature and method sources','Publications et sources méthodologiques','Publicaciones y fuentes metodológicas','Literatura eta metodoen iturriak'],source:['来源','Source','Source','Fuente','Iturria'],routes:['对应研究路线','Linked research routes','Axes de recherche associés','Líneas de investigación vinculadas','Lotutako ikerketa-ildoak'],openRoute:['查看对应研究路线','View linked research route','Voir l’axe de recherche associé','Ver línea de investigación vinculada','Ikusi lotutako ikerketa-ildoa'],
    noRoute:['当前目录尚无可连接的研究路线。','No linked research route is available in the current catalogue.','Aucun axe associé n’est disponible dans le catalogue actuel.','No hay una línea vinculada disponible en el catálogo actual.','Uneko katalogoan ez dago lotutako ikerketa-ildorik.'],empty:['没有符合当前筛选的 QTL','No QTLs match these filters','Aucun QTL ne correspond aux filtres','Ningún QTL coincide con los filtros','Ez dago iragazkiekin bat datorren QTLrik'],emptyHelp:['尝试缩写、全名或更宽的研究类别。','Try an abbreviation, full name or a broader research category.','Essayez un sigle, un nom complet ou une catégorie plus large.','Pruebe una sigla, un nombre completo o una categoría más amplia.','Saiatu laburdura, izen osoa edo ikerketa-kategoria zabalagoa erabiltzen.'],notLoaded:['QTL 目录尚未载入。','The QTL catalogue has not loaded.','Le catalogue QTL n’est pas chargé.','El catálogo QTL no se ha cargado.','QTL katalogoa ez da kargatu.']
  };
  const state={query:'',family:'all',open:new Set()},index=new WeakMap();
  const A=()=>window.YV_APP,lang=()=>LANGS.includes(A()?.prefs().language)?A().prefs().language:'en',T=k=>COPY[k]?.[LANGS.indexOf(lang())]||COPY[k]?.[1]||k;
  const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list=value=>Array.isArray(value)?value:[],hasHan=value=>/[\u3400-\u9fff]/u.test(value);
  function text(value,fallback=''){
    if(value&&typeof value==='object'&&!Array.isArray(value))return String(value[lang()]||value.en||fallback);
    const source=String(value??''),translated=A()?.tx?.(source)||source;
    return lang()!=='zh'&&hasHan(translated)?String(fallback):translated;
  }
  const recordText=(record,key)=>text(record?.[key],record?.[key+'En']||'');
  const rows=()=>list(A()?.data()?.projects?.qtlCatalogue);
  const catalogue=()=>A()?.data()||{};
  const normalize=value=>String(value??'').normalize('NFKD').replace(/\p{M}/gu,'').toLowerCase().trim();
  const flatten=value=>Array.isArray(value)?value.flatMap(flatten):value&&typeof value==='object'?Object.values(value).flatMap(flatten):typeof value==='string'?[value]:[];
  function searchIndex(row){if(!index.has(row))index.set(row,normalize(flatten([row.id,row.abbreviation,row.title,row.trait,row.keywords]).join(' ')));return index.get(row);}
  function filtered(){const tokens=normalize(state.query).split(/\s+/).filter(Boolean);return rows().filter(row=>(state.family==='all'||row.family===state.family)&&tokens.every(token=>searchIndex(row).includes(token)));}
  function counts(){const tokens=normalize(state.query).split(/\s+/).filter(Boolean),matches=rows().filter(row=>tokens.every(token=>searchIndex(row).includes(token)));return Object.fromEntries(['all',...FAMILIES].map(f=>[f,f==='all'?matches.length:matches.filter(row=>row.family===f).length]));}
  const inputText=id=>{const r=catalogue().categories?.dataRequirements?.find(r=>r.id===id);return r?recordText(r,'title'):String(id).replaceAll('_',' ');};
  const safeURL=value=>{try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:'';}catch{return '';}};
  function sourceIdentity(value){const url=safeURL(value);if(!url)return '';const parsed=new URL(url);if(/^(dx\.)?doi\.org$/i.test(parsed.hostname)){let doi=parsed.pathname.slice(1);try{doi=decodeURIComponent(doi);}catch{}return 'doi:'+doi.replace(/\/$/,'').toLowerCase();}return parsed.href.replace(/#.*$/,'').replace(/\/$/,'');}
  function sources(row){
    const papers=[...new Set(list(row.paperIds))].map(id=>catalogue().literature?.papers?.find(p=>p.id===id)).filter(Boolean);
    const paperURLs=new Set(papers.flatMap(p=>[p.url,p.doi?'https://doi.org/'+p.doi:''].map(sourceIdentity).filter(Boolean)));
    const seen=new Set(),urls=list(row.sourceUrls).map(safeURL).filter(url=>{const key=sourceIdentity(url);if(!key||paperURLs.has(key)||seen.has(key))return false;seen.add(key);return true;});
    if(!papers.length&&!urls.length)return '';
    return `<div class="qtl25-sources"><h4>${E(T('sources'))}</h4><ul>${papers.map(p=>{const title=typeof p.title==='string'?p.title:text(p.title,p.id),year=p.year||p.onlineYear;return `<li><button type="button" class="qtl25-paper" data-qtl-paper="${E(p.id)}">${E(title+(year?' ('+year+')':''))}<span aria-hidden="true"> ↗</span></button></li>`;}).join('')}${urls.map((url,i)=>{const sourceLabel=row.sourceLabels?.[url]||row.sourceLabels?.[list(row.sourceUrls).find(raw=>safeURL(raw)===url)];return `<li><a href="${E(url)}" target="_blank" rel="noopener noreferrer" title="${E(url)}">${E(text(sourceLabel)||T('source')+' '+(i+1)+' · '+new URL(url).hostname)}<span aria-hidden="true"> ↗</span></a></li>`;}).join('')}</ul></div>`;
  }
  const paragraph=(key,value)=>{const display=text(value);return display?`<div class="qtl25-field"><dt>${E(T(key))}</dt><dd>${E(display)}</dd></div>`:'';};
  const values=value=>Array.isArray(value)?value:value?[value]:[];
  function modeText(mode){if(mode?.title||mode?.description)return [text(mode.title),text(mode.description)].filter(Boolean).join(' — ');return text(mode);}
  function card(row){
    const tools=list(row.toolIds).map(id=>catalogue().workflow?.tools?.find(t=>t.id===id)).filter(Boolean),routes=list(row.routeIds).map(id=>catalogue().projects?.projects?.find(p=>p.id===id)).filter(Boolean);
    const id=String(row.id),inputs=list(row.inputs).map(inputText),additional=values(row.additionalInputs).map(v=>text(v)).filter(Boolean),modes=values(row.inputModes).map(modeText).filter(Boolean),metrics=values(row.metrics).map(v=>text(v)).filter(Boolean),metricRecords=[...new Set(list(row.metricIds))].map(id=>catalogue().workflow?.metrics?.find(m=>m.id===id)).filter(Boolean);
    return `<article class="qtl25-card" data-qtl-card="${E(id)}"><header><strong class="qtl25-abbreviation">${E(row.abbreviation||id)}</strong><span class="qtl25-family">${E(T(row.family))}</span></header><h3>${E(text(row.title,row.abbreviation||id))}</h3><p class="qtl25-trait">${E(text(row.trait))}</p><details data-qtl-details="${E(id)}" ${state.open.has(id)?'open':''}><summary>${E(T('details'))}</summary><dl>${paragraph('unit',row.unit)}${metrics.length||metricRecords.length?`<div class="qtl25-field"><dt>${E(T('metrics'))}</dt><dd><ul>${metrics.map(value=>`<li>${E(value)}</li>`).join('')}${metricRecords.map(metric=>`<li><button type="button" class="qtl25-metric" data-qtl-metric="${E(metric.id)}">${E(text(A().field?.('metrics',metric,'name')||metric.name,metric.nameEn||metric.id))}</button></li>`).join('')}</ul></dd></div>`:''}${inputs.length?`<div class="qtl25-field"><dt>${E(T('inputs'))}</dt><dd><ul>${inputs.map(v=>`<li>${E(v)}</li>`).join('')}</ul></dd></div>`:''}${additional.length?`<div class="qtl25-field"><dt>${E(T('additionalInputs'))}</dt><dd><ul>${additional.map(v=>`<li>${E(v)}</li>`).join('')}</ul></dd></div>`:''}${modes.length?`<div class="qtl25-field"><dt>${E(T('inputModes'))}</dt><dd><ul>${modes.map(v=>`<li>${E(v)}</li>`).join('')}</ul></dd></div>`:''}${paragraph('scope',row.scope)}${paragraph('biologyCaveat',row.biologyCaveat)}</dl>${tools.length?`<div class="qtl25-methods"><h4>${E(T('tools'))}</h4><div>${tools.map(tool=>`<button type="button" data-qtl-tool="${E(tool.id)}">${E(tool.name)}</button>`).join('')}</div></div>`:''}${sources(row)}</details><footer>${routes.length?`<span>${E(T('routes'))}</span>${routes.map(route=>`<button type="button" data-qtl-route="${E(route.id)}" aria-label="${E(T('openRoute')+' · '+recordText(route,'title'))}">${E(recordText(route,'title')||route.id)}<span aria-hidden="true"> ↗</span></button>`).join('')}`:`<p>${E(T('noRoute'))}</p>`}</footer></article>`;
  }
  function resultHTML(){const found=filtered();if(!rows().length)return `<div class="qtl25-empty"><p>${E(T('notLoaded'))}</p></div>`;return found.length?found.map(card).join(''):`<div class="qtl25-empty"><h3>${E(T('empty'))}</h3><p>${E(T('emptyHelp'))}</p><button type="button" data-qtl-reset>${E(T('reset'))}</button></div>`;}
  const status=()=>`${filtered().length} ${T('matches')} · ${T('of')} ${rows().length}`;
  function navigation(){const view=new URLSearchParams((globalThis.location?.hash||'').split('?')[1]||'').get('view')||'routes';return `<nav class="qtl25-navigation" aria-label="${E(T('navigation'))}">${[['routes','allRoutes','#projects'],['qtl','qtlTraits','#projects?view=qtl'],['coverage','coverage','#projects?view=coverage'],['evolution','evolution','#projects?view=evolution']].map(([id,label,href])=>`<a href="${href}" ${view===id?'aria-current="page"':''}>${E(T(label))}</a>`).join('')}</nav>`;}
  function panel(){const n=counts();return `<section class="qtl25" id="qtl-catalogue-v25e" aria-labelledby="qtl25-title"><header class="qtl25-heading"><div><h2 id="qtl25-title">${E(T('title'))}</h2><p>${E(T('intro'))}</p></div></header><div class="qtl25-searchbar" role="search"><label for="qtl25-query">${E(T('search'))}<input id="qtl25-query" type="search" data-qtl-query value="${E(state.query)}" placeholder="${E(T('searchHint'))}" autocomplete="off"></label><button type="button" data-qtl-reset>${E(T('reset'))}</button></div><div class="qtl25-filters" role="group" aria-label="${E(T('filters'))}">${['all',...FAMILIES].map(f=>`<button type="button" data-qtl-family="${f}" aria-pressed="${state.family===f}"><span>${E(T(f))}</span><small data-qtl-count="${f}">${n[f]}</small></button>`).join('')}</div><p class="qtl25-status" id="qtl25-status" role="status" aria-live="polite" aria-atomic="true">${E(status())}</p><div class="qtl25-grid" id="qtl25-results">${resultHTML()}</div></section>`;}
  function refresh(){const mount=document.getElementById('qtl-catalogue-v25e');if(!mount)return;const result=mount.querySelector('#qtl25-results'),summary=mount.querySelector('#qtl25-status');if(result)result.innerHTML=resultHTML();if(summary)summary.textContent=status();const n=counts();mount.querySelectorAll('[data-qtl-family]').forEach(button=>{button.setAttribute('aria-pressed',String(state.family===button.dataset.qtlFamily));const count=button.querySelector('[data-qtl-count]');if(count)count.textContent=n[button.dataset.qtlFamily];});}
  document.addEventListener('input',event=>{if(event.target?.dataset?.qtlQuery===undefined)return;state.query=event.target.value;refresh();});
  document.addEventListener('click',event=>{const family=event.target.closest?.('[data-qtl-family]');if(family&&['all',...FAMILIES].includes(family.dataset.qtlFamily)){state.family=family.dataset.qtlFamily;refresh();return;}const reset=event.target.closest?.('[data-qtl-reset]');if(reset){state.query='';state.family='all';const query=document.getElementById('qtl25-query');if(query)query.value='';refresh();query?.focus({preventScroll:true});return;}const route=event.target.closest?.('[data-qtl-route]');if(route&&catalogue().projects?.projects?.some(p=>p.id===route.dataset.qtlRoute)){A().openRecord('project',route.dataset.qtlRoute);return;}const metric=event.target.closest?.('[data-qtl-metric]');if(metric&&catalogue().workflow?.metrics?.some(m=>m.id===metric.dataset.qtlMetric)){A().openRecord('metric',metric.dataset.qtlMetric);return;}const paper=event.target.closest?.('[data-qtl-paper]');if(paper&&catalogue().literature?.papers?.some(p=>p.id===paper.dataset.qtlPaper)){A().openRecord('paper',paper.dataset.qtlPaper);return;}const tool=event.target.closest?.('[data-qtl-tool]');if(tool&&catalogue().workflow?.tools?.some(t=>t.id===tool.dataset.qtlTool))A().openRecord('tool',tool.dataset.qtlTool);});
  document.addEventListener('toggle',event=>{const id=event.target?.dataset?.qtlDetails;if(!id)return;if(event.target.open)state.open.add(id);else if(event.target.isConnected!==false)state.open.delete(id);},true);
  window.YV_QTL_CATALOGUE={panel,navigation,getState:()=>({query:state.query,family:state.family}),results:()=>filtered().map(row=>row.id)};
})();
